using System;

class Program
{
    static void Main()
    {
        // int → long (automatic, no data loss)
        int count = 50000;
        long bigCount = count;
        Console.WriteLine(bigCount); // 50000

        // int → double (automatic)
        int items = 42;
        double ratio = items;
        Console.WriteLine(ratio); // 42.0

        // char → int (Unicode code point)
        char letter = 'A';
        int code = letter;
        Console.WriteLine(code); // 65

        // Numeric promotion in expressions
        int x = 10;
        double y = 3.14;
        double result = x + y; // x promoted to double automatically
        Console.WriteLine(result); // 13.14
    }
}

using System;

class Program
{
    static void Main()
    {
        // double → int: truncates (does not round)
        double price = 19.99;
        int roundedDown = (int)price;
        Console.WriteLine(roundedDown); // 19 (not 20!)

        // long → int: possible overflow
        long bigNumber = 3_000_000_000;
        int smallNumber = (int)bigNumber; // Wraps around!
        Console.WriteLine(smallNumber); // -1294967296

        // checked context — throws OverflowException
        checked
        {
            try
            {
                int max = int.MaxValue;
                byte b = checked((byte)(max + 1));
                Console.WriteLine(b); // Won't reach here
            }
            catch (OverflowException ex)
            {
                Console.WriteLine($"Overflow caught: {ex.Message}");
            }
        }
    }
}

using System;

class Program
{
    static void Main()
    {
        // Parse — throws FormatException on invalid input
        string input1 = "123";
        int num1 = int.Parse(input1);
        Console.WriteLine(num1); // 123
        // int.Parse("abc"); // CRASH: FormatException

        // TryParse — returns bool, never throws
        string input2 = "456";
        if (int.TryParse(input2, out int num2))
        {
            Console.WriteLine($"Parsed: {num2}"); // Parsed: 456
        }
        else
        {
            Console.WriteLine("Invalid number format");
        }

        // TryParse with invalid input — safe!
        string input3 = "not-a-number";
        if (int.TryParse(input3, out int num3))
        {
            Console.WriteLine(num3);
        }
        else
        {
            Console.WriteLine("Could not parse — but no crash!");
        }

        // Available TryParse methods for other types
        double.TryParse("3.14", out double d);
        decimal.TryParse("99.99m", out decimal m);
        bool.TryParse("true", out bool b);
        DateTime.TryParse("2024-01-15", out DateTime dt);
    }
}

using System;

class Program
{
    static void Main()
    {
        // String to int
        string ageStr = "25";
        int age = Convert.ToInt32(ageStr);
        Console.WriteLine(age); // 25

        // String to double
        string priceStr = "19.99";
        double price = Convert.ToDouble(priceStr);
        Console.WriteLine(price); // 19.99

        // String to boolean
        string boolStr = "true";
        bool isActive = Convert.ToBoolean(boolStr);
        Console.WriteLine(isActive); // True

        // null converts to default value
        string? nullStr = null;
        int defaultValue = Convert.ToInt32(nullStr);
        Console.WriteLine(defaultValue); // 0

        // int to double
        int count = 42;
        double d = Convert.ToDouble(count);
        Console.WriteLine(d); // 42.0
    }
}
